import{_ as e,o as t,c as o,a4 as l}from"./chunks/framework.DzJZdBQK.js";const d=JSON.parse('{"title":"写作课作业-061","description":"","frontmatter":{"date":"2020-09-18T21:54:24","title":"写作课作业-061","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/061.md","filePath":"posts/homework/061.md"}'),i={name:"posts/homework/061.md"};function a(s,p,r,c,_,n){return t(),o("div",null,[...p[0]||(p[0]=[l("<blockquote><p>9.18写作作业：反复琢磨这个图（建议自己用excel表动手做一下），谈谈你思考和感悟。[微笑]</p></blockquote><p>看了这些表格的时候，知道是来自笑来老师的得到专栏《通往财富自由之路》，在写作群里说了句，专栏没做的作业迟早是要还的。</p><p>为什么呢？其实当时也把表格给做好了，看了几次，再看看当时自己的现状——工作不太顺，赚钱也不多，能力不见长——有点像被困在永恒的当下，于是在焦虑和忙碌中，忘了反复琢磨。</p><p>补作业容易，时间不会再等你。于是打开书本，重新读了一遍你的“长期”究竟有多长？表1是普通的指数增长，表2是增加定投策略的指数增长，表3是增加消耗的指数增长。</p><p>书中对这三个表格的结论是：</p><blockquote><ul><li>对能力越强的人来说，“长期”越短。</li><li>对能使用正确策略的人来说，“长期”更短。</li><li>对有能力在投资之外赚钱的人来说，“长期”更短。</li></ul></blockquote><p>我们常说人生是一场马拉松，我们用这个大家熟知的长跑比赛项目的数据来看看：</p><p>马拉松全程26.2英里（42.2千米）。</p><p>2019年10月12日，34岁的基普乔格（Eliud Kipchoge）以1:59:40创造新的世界记录。</p><p>而另一方面，数据显示，2018年，马拉松平均完赛时间是4:32:49。</p><p>而我，跑个5公里，就要花掉40分钟，而马拉松的长度是从不曾完成过。</p><p>如果距离是生命的话，表格的前提就是你要活得长，如果距离是投资的话，表格的前提就是你做得久。那么健身，让自己活久一点，趁早开始投资就显得很重要。</p><p>我们知道马拉松跑步时，虽也有冲刺阶段，但整个过程时相对匀速的，简化来看是线性变化，而不是指数变化，即便如此，能力强的人依然会以几倍自己速度的完成比赛，缩短这个“长期”。</p><p>如果从我自身的经历来看，我经历的是表3，也就是虽有增长，但也不断的消耗，始终没有看这自己的复利曲线。这个时候需要保持的是耐心呀，就算没有看到收益也要持续的耐心。</p><p>记得去年自己在公号上还发了篇《保持耐心做长期成长》的文章。</p><blockquote><p>前老板举例个奥数题的翻版的例子：</p><p>池塘里的荷花每天长一倍，30天长满一池塘，问多少天覆盖整个池塘的四分之一？</p><p>大家都抢着回答。我当时没有什么感觉，自己也不是智力出众型，不能马上答上来，所以把更多的注意力放了在如何做对这道题，而不显得那么傻上，现在想想也觉得好笑。</p><p>而现在回想起来老板是希望我们关注以下几点吧：</p><ul><li>关注的是指数增长。但我除了课堂的学习从未将它与生活，工作联系起来。</li><li>体会时间的重要性。但因为是按天来算的，反而我低估了时间的力量。</li><li>关注增长率，但因为是成倍增长，让我高估了成长率。</li></ul><p>一个例子被举出来时，听的人可能很大程度上不能感同身受，不能体会它的力量。但就像是种下一颗种子一样，在那等待生根发芽，静待花开，突然你会有一天发现，而后感叹。</p><p>从近期的学习来看，我的成长速度显然不大可能达不到荷花的程度，但保持足够的耐心，特别是接受自己起步时的不好，一定会看到一个指数的增长。</p></blockquote><p>做好了心理建设——要有耐心，我还需要做的是什么呢？引入策略，让自己立于不败之地。现在定投了BOX，BOX一涨就焦虑，慌呀——场外赚钱能力不足，买不起。然后缴足了费用，让自己上了船——下不来，让自己被动的获得耐心。</p><p>写作会可以锻炼人的思维方式，可以产生自己的影响力，会成为销售的一个手段。那现在的我其实在保证自己现有工作认真完成的情况下，我就是在不断的增强自己的能力，增加场外赚钱的机会。</p><p>种树最好的是十年前，其次是现在。一切才刚刚开始。</p>",19)])])}const m=e(i,[["render",a]]);export{d as __pageData,m as default};
